---
import type { HTMLAttributes } from "astro/types"
import ArrowRightIcon from "@lucide/astro/icons/arrow-right"

import { cn } from "@/lib/utils"
import { Banner, BannerContainer } from "@/components/ui/banner"

type Props = HTMLAttributes<"aside"> & {
  title: string
  description: string
  link: {
    label: string
    href: string
  }
  closeLabel: string
  storageKey?: string
}

const {
  class: className,
  title,
  description,
  link,
  closeLabel,
  storageKey,
  ...props
} = Astro.props
---

<Banner
  storageKey={storageKey}
  class={cn("dark bg-background text-foreground", className)}
  {...props}
>
  <BannerContainer
    class="flex-row items-center gap-x-4 gap-y-1"
    closeLabel={closeLabel}
  >
    <p class="text-sm leading-relaxed">
      <span class="font-semibold">{title}</span>{" "}
      <span class="mx-1.5 hidden opacity-50 sm:inline">&middot;</span>{" "}
      <span class="opacity-80">{description}</span>
    </p>
    <a
      href={link.href}
      class="group/link inline-flex shrink-0 items-center gap-1 text-sm font-medium underline underline-offset-4 transition-opacity hover:opacity-80"
    >
      {link.label}
      <ArrowRightIcon class="size-3.5 transition-transform group-hover/link:translate-x-0.5" />
    </a>
  </BannerContainer>
</Banner>
